import json
from fastmcp import FastMCP

server = FastMCP("config-server")

@server.resource(uri="data://config")
def get_config() -> str:
    config = {
        "name": "config",
        "version": "1.0.0",
        "settings": {
            "debug": False,
            "timeout": 30,
            "max_retries": 3
        }
    }
    return json.dumps(config, indent=2)

if __name__ == "__main__":
    server.run()
